    },
    "delete_draft": {
      "decision": "refuse",
      "reason": "Действие delete_draft не входит в область гранта ['publish', 'request_approval', 'keep_draft']. Удаление черновика не разрешено, и оснований для него нет."
    },
    "transfer_ownership": {
